extern S_SYSTEM_DATA *myData;
extern S_MODULE_DATA *myPs;
extern S_DIO *myDio;

void InOutControl(int index)
{
	int tmp;

	if(myDio->config.dio_Control_Flag == P0) {
		//kjg_111002
		switch(index) {
			case 0: //internal io
				I_InScan();
				tmp = I_In_FlagCheck_PowerSwitch();
				break;
			case 1: //module io
				break;
			case 2: //channel io
				break;
			case 3: //external io
				break;
			default: break;
		}

		return;
	}

	switch(index) {
		case 0: //internal io
			if(myDio->misc.delayTimer < myDio->config.dioDelay) {
				myDio->misc.delayTimer += myDio->config.scan_period;
			}
			I_InScan();
			I_In_FlagCheck();
			I_OutScan();
			break;
		case 1: //module io
			M_InScan();
			M_In_FlagCheck();
			M_OutScan();
			break;
		case 2: //channel io
			C_InScan();
			C_In_FlagCheck();
			break;
		case 3: //external io
			E_InScan();
			E_In_FlagCheck();
			E_OutScan();
			DIO_Signal();
			break;
		default: break;
	}
}

