int I_In_FlagCheck_Chamber_5(void)
{ //lki_111010
	//kjh_211021 unsigned char cmp_time1, cmp_time2;
	int rtn=0;//kjh_211021 timer2;
	S_MSG_VAL SendMsg;
	unsigned int cmp_time1, cmp_time2;	//kjh_211021
	long scan_period;	//kjh_211021

	//kjh_211021 cmp_time1 = 100; //1sec
	//kjh_211021 cmp_time2 = 30; //30sec
	//kjh_211021 timer2 = 30000; //30sec

	cmp_time1 = 1000; //1sec
	cmp_time2 = 30000; //30sec
	
	scan_period = myDio->config.scan_period;	//kjh_211021

	if(Read_InPoint(0, 0, I_JIG_CHAMBER_SMOKE) == P1) {
		if(myDio->signal[DIO_SIG_CHAMBER_SMOKE_FAIL]
			* scan_period < cmp_time1) {
			myDio->signal[DIO_SIG_CHAMBER_SMOKE_FAIL]++;
		} else if(myDio->signal[DIO_SIG_CHAMBER_SMOKE_FAIL]
			* scan_period == cmp_time1) {
			myDio->signal[DIO_SIG_CHAMBER_SMOKE_FAIL]++;
			memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
			SendMsg.msg = MSG_IO_MODULE_EXIT;
			SendMsg.val[0] = M_CD_FAULT_CHAMBER_SMOKE;
			SendMsg.val[1] = 0;
			send_msg(IO_TO_MODULE, (char *)&SendMsg);
			rtn = -1;
			Select_OutPoint(0, 0, O_MARS_LIGHT, ON);
			return rtn;
		}
	} else {
		myDio->signal[DIO_SIG_CHAMBER_SMOKE_FAIL] = P0;
	}
	if(Read_InPoint(0, 0, I_JIG_EXT_OT) == P1) {
		if(myDio->signal[DIO_SIG_EXT_OT_FAIL]
			* scan_period < cmp_time1) {
			myDio->signal[DIO_SIG_EXT_OT_FAIL]++;
		} else if(myDio->signal[DIO_SIG_EXT_OT_FAIL]
			* scan_period == cmp_time1) {
			myDio->signal[DIO_SIG_EXT_OT_FAIL]++;
			memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
			SendMsg.msg = MSG_IO_MODULE_EXIT;
			SendMsg.val[0] = M_CD_FAULT_EXT_OT;
			SendMsg.val[1] = 0;
			send_msg(IO_TO_MODULE, (char *)&SendMsg);
			rtn = -1;
			Select_OutPoint(0, 0, O_MARS_LIGHT, ON);
			return rtn;
		}
	} else {
		myDio->signal[DIO_SIG_EXT_OT_FAIL] = P0;
	}
	return rtn;
}

int I_In_FlagCheck_Chamber_6(void)
{ //jhkw_171015
	//kjh_211021 unsigned char cmp_time1, cmp_time2;
	int rtn=0;//kjh_211021 timer2;
	int	ch, smoke_count, ot_count;
	S_MSG_VAL SendMsg;
	unsigned int cmp_time1, cmp_time2;	//kjh_211021
	long scan_period;	//kjh_211021

	//kjh_211021 cmp_time1 = 100; //1sec
	//kjh_211021 cmp_time2 = 30; //30sec
	//kjh_211021 timer2 = 30000; //30sec

	cmp_time1 = 1000; //1sec
	cmp_time2 = 30000; //30sec

	scan_period = myDio->config.scan_period;	//kjh_211021

	smoke_count = ot_count = ch = 0;

	for(ch=0; ch < MAX_CH_4; ch++) {
		if(Read_InPoint(0, ch+1, I_JIG_CHAMBER_SMOKE) == P1) {
			smoke_count += (ch+1);
			ch = smoke_count;	//jhkw_200902
			break; 				//jhkw_200902
		}
	}

	if(smoke_count > 0) {
		if(myDio->signal[DIO_SIG_CHAMBER_SMOKE_FAIL]
			* scan_period < cmp_time1) {
			myDio->signal[DIO_SIG_CHAMBER_SMOKE_FAIL]++;
		} else if(myDio->signal[DIO_SIG_CHAMBER_SMOKE_FAIL]
			* scan_period == cmp_time1) {
			myDio->signal[DIO_SIG_CHAMBER_SMOKE_FAIL]++;
			memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
			SendMsg.msg = MSG_IO_MODULE_EXIT;
			SendMsg.val[0] = M_CD_FAULT_CHAMBER_SMOKE;
			SendMsg.val[1] = 10 * ch + 1;
			send_msg(IO_TO_MODULE, (char *)&SendMsg);
			rtn = -1;
			Select_OutPoint(0, 0, O_MARS_LIGHT, ON);
			return rtn;
		}
	} else {
		myDio->signal[DIO_SIG_CHAMBER_SMOKE_FAIL] = P0;
	}

	for(ch=0; ch < MAX_CH_4; ch++) {
		if(Read_InPoint(0, ch+1, I_JIG_EXT_OT) == P1) {
			ot_count += (ch+1);
			ch = ot_count;	//kjh_211021
			break;	//kjh_211021
		}
	}

	if(ot_count > 0) {
		if(myDio->signal[DIO_SIG_EXT_OT_FAIL]
			* scan_period < cmp_time1) {
			myDio->signal[DIO_SIG_EXT_OT_FAIL]++;
		} else if(myDio->signal[DIO_SIG_EXT_OT_FAIL]
			* scan_period == cmp_time1) {
			myDio->signal[DIO_SIG_EXT_OT_FAIL]++;
			memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
			SendMsg.msg = MSG_IO_MODULE_EXIT;
			SendMsg.val[0] = M_CD_FAULT_EXT_OT;
			SendMsg.val[1] = 10 * ch + 1;
			send_msg(IO_TO_MODULE, (char *)&SendMsg);
			rtn = -1;
			Select_OutPoint(0, 0, O_MARS_LIGHT, ON);
			return rtn;
		}
	} else {
		myDio->signal[DIO_SIG_EXT_OT_FAIL] = P0;
	}
	return rtn;
}

int I_In_FlagCheck_Chamber_7(int chamber_group)
{ //csk_190527
	//kjh_211021 unsigned char cmp_time1, off_check_flag1, off_check_flag2;
	unsigned char off_check_flag1, off_check_flag2;
	unsigned int cmp_time1; //kjh_211021
	int rtn=0, group, ch, ch_per_chamber;
	S_MSG_VAL SendMsg;
	long scan_period;	//kjh_211021

	//kjh_211021 cmp_time1 = 100; //1sec / ch_per_chamber
	cmp_time1 = 1000; //1sec / ch_per_chamber
	scan_period = myDio->config.scan_period;	//kjh_211021

	off_check_flag1 = off_check_flag2 = 0x00;
	group = 0; ch = 0;
	ch_per_chamber = (myPs->config.installedCh / chamber_group);

	if((chamber_group == 1) || (chamber_group == 2)) {
		for(ch=0; ch < ch_per_chamber; ch++) {
			if(Read_InPoint(0, ch+1, I_JIG_CHAMBER_OVER_TEMP) == P1) {
				if(myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL]
					* scan_period < cmp_time1) {
					myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL]++;
				}
				if(ch == 0) off_check_flag1 |= 0x01;
				if(ch == 1) off_check_flag1 |= 0x02;
				if(ch == 2) off_check_flag1 |= 0x04;
				if(ch == 3) off_check_flag1 |= 0x08;
			} else {
			}
		}
	}

	if(chamber_group == 2) {
		for(ch = ch_per_chamber; ch < myPs->config.installedCh; ch++) {
			if(Read_InPoint(1, ch+1, I_JIG_CHAMBER_OVER_TEMP) == P1) {
				if(myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL_2]
					* scan_period < cmp_time1) {
					myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL_2]++;
				}
				if(ch == 0) off_check_flag2 |= 0x01;
				if(ch == 1) off_check_flag2 |= 0x02;
				if(ch == 2) off_check_flag2 |= 0x04;
				if(ch == 3) off_check_flag2 |= 0x08;
			} else {
			}
		}
	}

	if(off_check_flag1 == 0x00)
		myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL] = 0;
	if(off_check_flag2 == 0x00)
		myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL_2] = 0;

	if(myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL]
		* scan_period >= cmp_time1) {
		for(ch=0; ch < ch_per_chamber; ch++) {
			memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
			SendMsg.msg = MSG_IO_MODULE_CH_PAUSE;
			SendMsg.val[0] = C_CD_FAULT_CHAMBER_FAULT;
			SendMsg.val[1] = ch;
			send_msg(IO_TO_MODULE, (char *)&SendMsg);
		}
	}

	if((chamber_group == 2)
		&& (myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL_2]
		* scan_period >= cmp_time1)) {
		for(ch= ch_per_chamber; ch < myPs->config.installedCh; ch++) {
			memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
			SendMsg.msg = MSG_IO_MODULE_CH_PAUSE;
			SendMsg.val[0] = C_CD_FAULT_CHAMBER_FAULT;
			SendMsg.val[1] = ch;
			send_msg(IO_TO_MODULE, (char *)&SendMsg);
		}
	}

	return rtn;
}

int I_In_FlagCheck_Chamber_8(void)
{	//ktg_230215 
	unsigned char off_check_flag1, off_check_flag2;
	unsigned char off_check_flag3, off_check_flag4;
	unsigned int cmp_time1; //kjh_211021
	int rtn=0, group, ch;
	S_MSG_VAL SendMsg;
	long scan_period;	//kjh_211021

	cmp_time1 = 1000; //1sec / ch_per_chamber
	scan_period = myDio->config.scan_period;	//kjh_211021

	off_check_flag1 = 0x00;
	off_check_flag2 = 0x00;
	off_check_flag3 = 0x00;
	off_check_flag4 = 0x00;
	group = 0; ch = 0;

	for(ch=0; ch < myPs->config.installedCh; ch++) {
		if(Read_InPoint(0, ch+1, I_JIG_CHAMBER_OVER_TEMP) == P1) {
			if(ch == 0) {
				if(myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL]
					* scan_period < cmp_time1) {
					myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL]++;
				}
				off_check_flag1 |= 0x01;
			} else if(ch == 1) {
				if(myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL_2]
					* scan_period < cmp_time1) {
					myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL_2]++;
				}
				off_check_flag2 |= 0x01;
			} else if(ch == 2) {
				if(myDio->signal[DIO_SIG_CHAMBER_EMG_FAIL]
					* scan_period < cmp_time1) {
					myDio->signal[DIO_SIG_CHAMBER_EMG_FAIL]++;
				}
				off_check_flag3 |= 0x01;
			} else if(ch == 3) {
				if(myDio->signal[DIO_SIG_CHAMBER_POWER_FAIL]
					* scan_period < cmp_time1) {
					myDio->signal[DIO_SIG_CHAMBER_POWER_FAIL]++;
				}
				off_check_flag4 |= 0x01;
			}
		}
	}

	if(off_check_flag1 == 0x00)
		myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL] = P0;
	if(off_check_flag2 == 0x00)
		myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL_2] = P0;
	if(off_check_flag3 == 0x00)
		myDio->signal[DIO_SIG_CHAMBER_EMG_FAIL] = P0;
	if(off_check_flag4 == 0x00)
		myDio->signal[DIO_SIG_CHAMBER_POWER_FAIL] = P0;

	if(myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL]
		* scan_period >= cmp_time1) {
		ch = 0;
		memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
		SendMsg.msg = MSG_IO_MODULE_CH_PAUSE;
		SendMsg.val[0] = C_CD_FAULT_CHAMBER_FAULT;
		SendMsg.val[1] = ch;
		send_msg(IO_TO_MODULE, (char *)&SendMsg);
	}

	if(myDio->signal[DIO_SIG_CHAMBER_OVER_TEMP_FAIL_2]
		* scan_period >= cmp_time1) {
		ch = 1;
		memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
		SendMsg.msg = MSG_IO_MODULE_CH_PAUSE;
		SendMsg.val[0] = C_CD_FAULT_CHAMBER_FAULT;
		SendMsg.val[1] = ch;
		send_msg(IO_TO_MODULE, (char *)&SendMsg);
	}

	if(myDio->signal[DIO_SIG_CHAMBER_EMG_FAIL]
		* scan_period >= cmp_time1) {
		ch = 2;
		memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
		SendMsg.msg = MSG_IO_MODULE_CH_PAUSE;
		SendMsg.val[0] = C_CD_FAULT_CHAMBER_FAULT;
		SendMsg.val[1] = ch;
		send_msg(IO_TO_MODULE, (char *)&SendMsg);
	}
	
	if(myDio->signal[DIO_SIG_CHAMBER_POWER_FAIL]
		* scan_period >= cmp_time1) {
		ch = 3;
		memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
		SendMsg.msg = MSG_IO_MODULE_CH_PAUSE;
		SendMsg.val[0] = C_CD_FAULT_CHAMBER_FAULT;
		SendMsg.val[1] = ch;
		send_msg(IO_TO_MODULE, (char *)&SendMsg);
	}
	return rtn;
}


int I_In_FlagCheck_Fan(void)
{
	unsigned char tmp;
	int rtn=0, group, ch, count;
	S_MSG_VAL SendMsg;

	if((myPs->misc.timer_1sec - myPs->misc.fan_fail_detect_time) <= 10) {
		myPs->misc.fan_fail_detect_time2 = myPs->misc.timer_1sec;
		return rtn;
	}

	group = 0; ch = 0; count = 0;
	for(ch=0; ch < 10; ch++) {
		if(Read_InPoint(group, ch+1, I_FAN_FAIL) == ON) {
			count++;
		}
	}

	if(count == 0) {
		myPs->misc.fan_fail_detect_time2 = myPs->misc.timer_1sec;
		myDio->signal[DIO_SIG_FAN_FAIL] = P0;
	} else {
		if((myPs->misc.timer_1sec - myPs->misc.fan_fail_detect_time2) <= 10) {
			return rtn;
		}

		if(myDio->signal[DIO_SIG_FAN_FAIL] < P2) {
			myDio->signal[DIO_SIG_FAN_FAIL]++;
		} else {
			if(myPs->signal[M_SIG_FAN_ACTIVE] == P10) {
				if(myPs->code == M_CD_FAULT_FAN
					|| myPs->code == M_CD_FAULT_AC_POWER_SHORT
					|| myPs->code == M_CD_FAULT_AC_POWER_LONG
					|| myPs->code == M_CD_FAULT_MAIN_EMG_SWITCH
					|| myPs->code == M_CD_FAULT_SUB_EMG_SWITCH
					|| myPs->code == M_CD_FAULT_MAIN_PS) {
					tmp = 0;
				} else {
					tmp = 1;
				}
				if(tmp == 1) {
					memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
					SendMsg.msg = MSG_IO_MODULE_EXIT;
					SendMsg.val[0] = M_CD_FAULT_FAN;
					SendMsg.val[1] = 0;
					send_msg(IO_TO_MODULE, (char *)&SendMsg);
					rtn = -1;
					myPs->signal[M_SIG_FAN_ACTIVE] = P11;
				}
			} else {
				myDio->signal[DIO_SIG_FAN_FAIL] = P0;
				//kjg_100302 if(myPs->code == M_CD_FAULT_FAN) myPs->code = M_CD_NONE;
			}
		}
	}

	return rtn;
}

int I_In_FlagCheck_BreakDown(void)
{
	int rtn=0, ch;
	unsigned int cmp_time1;
	unsigned char off_check_flag[4];
	S_MSG_VAL SendMsg;
	long scan_period;

	cmp_time1 = 1000; 
	scan_period = myDio->config.scan_period;
	off_check_flag[0] = 0x00;
	off_check_flag[1] = 0x00;
	off_check_flag[2] = 0x00;
	off_check_flag[3] = 0x00;

	if(myPs->config.BreakDownCheck == 1) {
		for(ch=0; ch < myPs->config.installedCh; ch++) {
			if(Read_InPoint(0, ch+1, I_BREAKDOWN_VOLTAGE) == P1) {
				if(myDio->signal[DIO_SIG_BREAKDOWN_VOLTAGE_1 + ch]
					* scan_period < cmp_time1) {
					myDio->signal[DIO_SIG_BREAKDOWN_VOLTAGE_1 + ch]++;
					off_check_flag[ch] = 0x01;
				}
			}
		}
	} else {
		return rtn;
	}


	for(ch=0; ch < myPs->config.installedCh; ch++) {
		if(off_check_flag[ch] == 0x00) {
			myDio->signal[DIO_SIG_BREAKDOWN_VOLTAGE_1 + ch] = P0;
		}
		if(myDio->signal[DIO_SIG_BREAKDOWN_VOLTAGE_1 + ch]
			* scan_period >= cmp_time1) {
			memset((char *)&SendMsg, 0, sizeof(S_MSG_VAL));
			SendMsg.msg = MSG_IO_MODULE_CH_PAUSE;
			SendMsg.val[0] = C_CD_FAULT_BREAKDOWN_VOLTAGE;
			SendMsg.val[1] = ch;
			myDio->signal[DIO_SIG_BREAKDOWN_VOLTAGE_1 + ch] = P0;
			Select_OutPoint(0, ch+1, O_CHAMBER_CH_WARNING, ON);
			send_msg(IO_TO_MODULE, (char *)&SendMsg);
		}
	}
	return rtn;
}
void I_OutScan(void)
{
	unsigned char flag, pn;
	int outByte, bit, point, byte_index, addr;

	for(outByte=0; outByte < MAX_DIO_IO_BYTES; outByte++) {
		byte_index = outByte;

		flag = 0x01;
		for(bit=0; bit < BITS_PER_BYTE; bit++) {
			point = byte_index * BITS_PER_BYTE + bit;

			if(myDio->function_set.out_set[point].use == USE) {
				pn = myDio->function_set.out_set[point].pn;

				if(myDio->out.function[point] == ON) {
					if(pn == ACTIVE_HIGH) {
						myDio->out.bytes[byte_index] |= flag;
					} else {
						myDio->out.bytes[byte_index] &= ~flag;
					}
				} else {
					if(pn == ACTIVE_HIGH) {
						myDio->out.bytes[byte_index] &= ~flag;
					} else {
						myDio->out.bytes[byte_index] |= flag;
					}
				}
			}
			flag = flag << 1;
		}

		addr = myDio->function_set.out_address[byte_index];
		if(addr == 0) continue;

		outb(myDio->out.bytes[byte_index], addr);
	}
}

void M_InScan(void)
{
	unsigned char flag, input, pn;
	int sensCount, inByte, position, point, byte_index, addr;

	if(myDio->misc.delayTimer < myDio->config.dioDelay) return;

	for(inByte=0; inByte < MAX_DIO_MI_BYTES; inByte++) {
		byte_index = MAX_DIO_II_BYTES + inByte;
		addr = myDio->function_set.in_address[byte_index];
		if(addr == 0) continue;

		input = inb(addr);
		myDio->in.bytes[byte_index] = input;

		flag = 0x01;
		for(position=0; position < BITS_PER_BYTE; position++) {
			point = byte_index * BITS_PER_BYTE + position;

			if(myDio->function_set.in_set[point].use == USE) {
				pn = myDio->function_set.in_set[point].pn;
				sensCount = (int)myDio->function_set.in_set[point].count;

				myDio->in.function[point]
					= InCheck(point, input & flag, pn, sensCount);
			}
			flag = flag << 1;
		}
	}
}

